to service_role;

create or replace function public.reserve_study_profile_report_email_delivery(payload jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  resolved_response_id uuid := (payload ->> 'responseId')::uuid;
  resolved_lead_id uuid;
  next_allowed_at timestamptz;
  daily_attempt_count bigint;
  earliest_daily_attempt timestamptz;
  retry_after_seconds integer;
begin
  select lead_id
  into resolved_lead_id
  from public.study_profile_responses
  where id = resolved_response_id;

  if resolved_lead_id is null then
    return null;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext(resolved_lead_id::text)
  );

  select report_email_next_allowed_at
  into next_allowed_at
  from public.study_profile_leads
  where id = resolved_lead_id
  for update;

  select count(*), min(reserved_at)
  into daily_attempt_count, earliest_daily_attempt
  from public.study_profile_email_delivery_attempts
  where lead_id = resolved_lead_id
    and reserved_at > now() - interval '24 hours';

  if daily_attempt_count >= 5 then
    retry_after_seconds := least(
      86400,
      greatest(
        1,
        ceil(extract(epoch from (
          earliest_daily_attempt + interval '24 hours' - now()
        )))::integer
      )
    );

    update public.study_profile_responses
    set
      email_delivery_status = 'skipped',
      email_last_attempted_at = now()
    where id = resolved_response_id;

    return jsonb_build_object(
      'allowed', false,
      'reason', 'daily_cap',
      'retryAfterSeconds', retry_after_seconds
    );
  end if;

  if next_allowed_at is null or next_allowed_at <= now() then
    insert into public.study_profile_email_delivery_attempts (
      lead_id,
      response_id,
      delivery_kind
    ) values (
      resolved_lead_id,
      resolved_response_id,
      'report'
    );

    update public.study_profile_leads
    set report_email_next_allowed_at = now() + interval '15 minutes'
    where id = resolved_lead_id;

    update public.study_profile_responses
    set email_last_attempted_at = now()
    where id = resolved_response_id;

    return jsonb_build_object(
      'allowed', true,
      'reason', null,
      'retryAfterSeconds', 0
    );
  end if;

  retry_after_seconds := greatest(
    1,
    ceil(extract(epoch from (next_allowed_at - now())))::integer
  );

  update public.study_profile_responses
  set
    email_delivery_status = 'skipped',
    email_last_attempted_at = now()
  where id = resolved_response_id;

  return jsonb_build_object(
    'allowed', false,
    'reason', 'cooldown',
    'retryAfterSeconds', retry_after_seconds
  );
end;
$$;

revoke all on function public.reserve_study_profile_report_email_delivery(jsonb)
from public, anon, authenticated;

grant execute on function public.reserve_study_profile_report_email_delivery(jsonb)
to service_role;

