      and (
        select count(*) = 11
        from information_schema.columns
        where table_schema = 'public'
          and table_name = 'study_profile_waitlist_confirmations'
          and column_name in (
            'token_hash',
            'consumed_token_hash',
            'status',
            'consent_copy_version',
            'consent_source',
            'age_confirmed',
            'expires_at',
            'resend_after',
            'confirmed_at',
            'replay_expires_at',
            'delivery_status'
          )
      )
      and pg_catalog.to_regclass(
        'public.study_profile_waitlist_confirmations_report_state_idx'
      ) is not null
      and pg_catalog.to_regclass(
        'public.study_profile_waitlist_confirmations_replay_cleanup_idx'
      ) is not null
      and coalesce((
        select relrowsecurity
        from pg_catalog.pg_class
        where oid = pg_catalog.to_regclass(
          'public.study_profile_waitlist_confirmations'
        )
      ), false) as pending_confirmation_columns,
      pg_catalog.to_regprocedure(
        'public.request_study_profile_waitlist_confirmation(jsonb)'
